// Validate telemetry payload and normalize fields
// Expected: {device, ts, ldr, threshold, mode, auto_decision_led, led}

const p = msg.payload || {};

function isNum(x){return typeof x === 'number' && isFinite(x);}

// Basic validation
if (!p.device) p.device = "unknown";
if (!isNum(p.ldr)) return null;
if (!isNum(p.threshold)) p.threshold = 500;
if (!p.mode) p.mode = "AUTO";

// Enforce range checks
if (p.ldr < 0 || p.ldr > 4095) {
  msg.anomaly = true;
} else {
  msg.anomaly = false;
}

// Provide a clean message for downstream
msg.telemetry = {
  device: String(p.device),
  ts: isNum(p.ts) ? p.ts : Math.floor(Date.now()/1000),
  ldr: p.ldr,
  threshold: p.threshold,
  mode: String(p.mode),
  auto_decision_led: !!p.auto_decision_led,
  led: !!p.led
};

// For UI nodes
msg.payload = msg.telemetry;
return msg;

// Digital Twin + Policy enforcement
// Policy: LED ON time <= 60% within last 10 minutes (rolling window)
// Human override: context.human.mode in {AUTO, ON, OFF}

const t = msg.telemetry;
const nowMs = Date.now();

// ---- Digital Twin model (simple expected band + residual) ----
// Define an "expected" band around threshold; this is a lightweight twin.
const expectedCenter = t.threshold;
const band = 150; // expected +/- band
const expectedLow = Math.max(0, expectedCenter - band);
const expectedHigh = Math.min(4095, expectedCenter + band);

let residual = 0;
if (t.ldr < expectedLow) residual = expectedLow - t.ldr;
else if (t.ldr > expectedHigh) residual = t.ldr - expectedHigh;

// Keep short history (for twin visualization)
let hist = context.get('ldr_hist') || [];
hist.push({ts: nowMs, ldr: t.ldr, led: t.led});
// keep last 5 minutes for history
const HIST_MS = 5 * 60 * 1000;
hist = hist.filter(e => (nowMs - e.ts) <= HIST_MS);
context.set('ldr_hist', hist);

// ---- Human-in-the-loop mode ----
const human = context.get('human') || { mode: 'AUTO' }; // AUTO / ON / OFF

// ---- Baseline decision (AI/rules) ----
// Use the device's suggested auto_decision as baseline (explainable)
const baseDecision = !!t.auto_decision_led;

// ---- Policy window tracking (10 minutes) ----
let win = context.get('policy_win') || [];
// win entries: {ts, led} sampled at telemetry rate
win.push({ts: nowMs, led: baseDecision});
const WIN_MS = 10 * 60 * 1000;
win = win.filter(e => (nowMs - e.ts) <= WIN_MS);
context.set('policy_win', win);

// Approximate ON ratio from samples
const onCount = win.reduce((a,e)=> a + (e.led ? 1 : 0), 0);
const ratioOn = win.length ? (onCount / win.length) : 0;

// Policy: allow ON only if ratio <= 0.60 (or turning ON would exceed)
// We'll be conservative: if baseDecision==true and ratioOn>0.60 -> block
let policyBlocked = false;
let policyReason = "";
let finalMode = human.mode;

let finalDecision;

if (finalMode === 'ON') {
  // Human forces ON, but still show policy warning (do not block human here)
  finalDecision = true;
  if (ratioOn > 0.60) {
    policyBlocked = true;
    policyReason = "Policy limit exceeded (ON ratio > 60%); human override active";
  }
} else if (finalMode === 'OFF') {
  finalDecision = false;
} else {
  // AUTO mode: policy can constrain
  if (baseDecision === true && ratioOn > 0.60) {
    finalDecision = false;
    policyBlocked = true;
    policyReason = "Policy enforced: energy-saving constraint (ON ratio > 60% in 10 min)";
  } else {
    finalDecision = baseDecision;
  }
}

// ---- Build Digital Twin state object ----
const twin = {
  expected: { center: expectedCenter, low: expectedLow, high: expectedHigh },
  residual: residual,
  residual_level: residual === 0 ? "NORMAL" : (residual < 120 ? "WARN" : "ALERT"),
  window_on_ratio: ratioOn,
  policy_blocked: policyBlocked,
  policy_reason: policyReason,
  human_mode: finalMode,
  base_decision: baseDecision,
  final_decision: finalDecision
};

context.set('twin', twin);

// ---- Prepare MQTT command to ESP32 ----
// We'll send mode commands only (AUTO/ON/OFF) to keep the device robust.
// In AUTO mode, ESP32 will follow its local decision; policy is enforced by switching to OFF if needed.
// Here we implement:
//  - If human_mode==ON -> send {mode:"ON"}
//  - If human_mode==OFF -> send {mode:"OFF"}
//  - If AUTO and finalDecision==true -> send {mode:"AUTO"} (ESP32 turns ON by threshold)
//  - If AUTO and finalDecision==false but baseDecision==true and policy blocked -> we can force OFF
//    to override local AUTO.

let cmd;
let explain;

if (finalMode === 'ON') {
  cmd = { mode: "ON" };
  explain = "Human override: LED forced ON";
} else if (finalMode === 'OFF') {
  cmd = { mode: "OFF" };
  explain = "Human override: LED forced OFF";
} else {
  // AUTO
  if (policyBlocked) {
    cmd = { mode: "OFF" };
    explain = twin.policy_reason;
  } else {
    cmd = { mode: "AUTO" };
    explain = baseDecision ? "AUTO decision: LED ON (below threshold)" : "AUTO decision: LED OFF (above threshold)";
  }
}

// For downstream (UI + MQTT)
msg.twin = twin;
msg.command = cmd;
msg.explain = explain;

// Multi-output style through node-wiring: set msg.payload for UI, clone for MQTT
return msg;

const cmd = msg.command || {mode:"AUTO"};
msg.payload = cmd;
msg.topic = "cps/esp32/lab01/command";
return msg;

const m = String(msg.payload || 'AUTO').toUpperCase();
const allowed = ['AUTO','ON','OFF'];
const mode = allowed.includes(m) ? m : 'AUTO';

const human = context.get('human') || { mode: 'AUTO' };
human.mode = mode;
context.set('human', human);

msg.payload = `Human mode set to ${mode}`;
return msg;

context.set('policy_win', []);
msg.payload = 'Policy window reset.';
return msg;
